# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the SmashDb console's value, with no UI code: a query, its result and the queries run
#          before it, on a SmashDb (the session's `db`, so tables made here exist in the Python
#          cells and the other way round). Running a query gives a new DbConsole, which replaces
#          the old one at its slot (Session.put), as a tool form's run does.
# Usage: console = DbConsole(db).run("select * from char")  ->  console.df, console.sql
#        Shown by render.py (kind "smashdb"); added with the Results tab bar's "+" (widgets.py).
# ---------------------------------------------------------------------------
from __future__ import annotations

import dataclasses
import time
from typing import TYPE_CHECKING

import polars as pl

if TYPE_CHECKING:
    from ds.data import SmashDb

# Queries kept in a console's history.
MAX_HISTORY = 20


def clean_sql(text: str) -> str:
    """A query as it is run: no surrounding space, no closing semicolon."""
    return text.strip().rstrip(";").strip()


@dataclasses.dataclass
class DbTable:
    """One table in the console's schema tree, as the browser shows it."""

    name: str = ""
    rows: str = ""
    """Its row count, as text ("" when it can't be counted)."""
    open: bool = False
    """Its columns are unfolded."""
    columns: list[dict[str, str]] = dataclasses.field(default_factory=list)
    """Each: name, dtype."""


@dataclasses.dataclass
class DbConsole:
    db: SmashDb = dataclasses.field(repr=False)
    sql: str = ""
    """The query that made df ("" = nothing run yet)."""
    df: pl.DataFrame | None = dataclasses.field(default=None, repr=False)
    seconds: float = 0.0
    """How long the query took."""
    history: tuple[str, ...] = ()
    """The queries that ran, newest first, each once (at most MAX_HISTORY)."""

    def run(self, sql: str) -> DbConsole:
        """A new console holding the query's result. A query that fails raises polars' own error
        (the app shows it as a traceback, as under a Python cell); this console is left as it is."""
        query = clean_sql(sql)
        start = time.perf_counter()
        df = self.db.sql(query)
        seconds = time.perf_counter() - start
        history = (query, *[past for past in self.history if past != query])[:MAX_HISTORY]
        return DbConsole(self.db, query, df, seconds, history)

    def schema(self) -> dict[str, list[str]]:
        """{table: its columns}, read from the db now (a query may have made or dropped a table)."""
        return {table: list(columns) for table, columns in self.db.schema().items()}

    def tables(self, opened: tuple[str, ...] | list[str] = ()) -> list[DbTable]:
        """The schema tree: every table with its row count, columns and dtypes."""
        tables = []
        for name, columns in self.db.schema().items():
            try:
                rows = f"{self.db.sql(f'select count(*) from "{name}"').item():,}"
            except Exception:  # noqa: BLE001  # a table that can't be counted is still listed
                rows = ""
            tables.append(
                DbTable(
                    name=name,
                    rows=rows,
                    open=name in opened,
                    columns=[{"name": column, "dtype": str(dtype)} for column, dtype in columns.items()],
                )
            )
        return tables

    @property
    def timing(self) -> str:
        """How long the query took, eg '3 ms' or '1.2 s'."""
        return f"{self.seconds * 1000:.0f} ms" if self.seconds < 1 else f"{self.seconds:.1f} s"
